import React, { useState } from 'react';
import { Category } from '../types';

interface CategorySelectorProps {
  onSelect: (category: Category) => void;
}

export const CategorySelector: React.FC<CategorySelectorProps> = ({ onSelect }) => {
  const categories: { value: Category; label: string; emoji: string }[] = [
    { value: 'jobs', label: 'Jobs', emoji: '💼' },
    { value: 'movies', label: 'Movies', emoji: '🎬' },
    { value: 'games', label: 'Games', emoji: '🎮' }
  ];

  return (
    <div className="w-full max-w-2xl mx-auto p-6 bg-white rounded-lg shadow-lg">
      <h2 className="text-2xl font-bold mb-6 text-center">Choose today's category</h2>
      
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        {categories.map((cat) => (
          <button
            key={cat.value}
            onClick={() => onSelect(cat.value)}
            className="p-6 bg-gradient-to-br from-blue-50 to-blue-100 hover:from-blue-100 hover:to-blue-200 rounded-lg font-semibold text-lg transition-all"
          >
            <div className="text-4xl mb-2">{cat.emoji}</div>
            {cat.label}
          </button>
        ))}
      </div>
    </div>
  );
};
